"""Read one explicit UTF-8 input path and display validated active IDs."""

import argparse
import json
from pathlib import Path

from .quantities import active_ids


def _unique_object(pairs: list[tuple[str, object]]) -> dict[str, object]:
    result: dict[str, object] = {}
    for key, value in pairs:
        if key in result:
            raise ValueError(f"duplicate JSON member: {key}")
        result[key] = value
    return result


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--input", type=Path, required=True)
    parser.add_argument("--output", type=Path, help="Exclusive UTF-8 output file; never overwrite")
    args = parser.parse_args(argv)
    payload: object = json.loads(
        args.input.read_text(encoding="utf-8"), object_pairs_hook=_unique_object,
    )
    ids = active_ids(payload)
    message = "Active IDs: " + ", ".join(ids)
    if args.output is None:
        print(message)
    else:
        with args.output.open("x", encoding="utf-8", newline="\n") as stream:
            stream.write(message + "\n")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

